import{_ as e,o as a,c as l,ao as s}from"./chunks/framework.neklfv_E.js";const f=JSON.parse('{"title":"The binders, and what distinguishes them","description":"","frontmatter":{},"headers":[],"relativePath":"manual/binder_families.md","filePath":"manual/binder_families.md","lastUpdated":null}'),n={name:"manual/binder_families.md"};function i(r,t,o,d,h,g){return a(),l("div",null,[...t[0]||(t[0]=[s('<h1 id="man-binder-families" tabindex="-1">The binders, and what distinguishes them <a class="header-anchor" href="#man-binder-families" aria-label="Permalink to &quot;The binders, and what distinguishes them {#man-binder-families}&quot;">​</a></h1><p>A &quot;cement&quot; is not one material. EN 197-1 recognizes five main types and some twenty-seven products, and the difference between them is <strong>how much of the clinker has been replaced, and by what</strong>. That single question decides the chemistry: which elements enter the paste, which hydrates can form, and which of this package&#39;s models the calculation needs.</p><p>This page is the map. The calculations themselves are on the pages it points to.</p><h2 id="The-families" tabindex="-1">The families <a class="header-anchor" href="#The-families" aria-label="Permalink to &quot;The families {#The-families}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">type</th><th style="text-align:left;">name</th><th style="text-align:right;">clinker</th><th style="text-align:left;">main other constituent</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>CEM I</strong></td><td style="text-align:left;">Portland</td><td style="text-align:right;">95–100 %</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong>CEM II/A-S</strong></td><td style="text-align:left;">Portland-slag</td><td style="text-align:right;">80–94 %</td><td style="text-align:left;">blastfurnace slag 6–20 %</td></tr><tr><td style="text-align:left;"><strong>CEM II/B-S</strong></td><td style="text-align:left;">Portland-slag</td><td style="text-align:right;">65–79 %</td><td style="text-align:left;">blastfurnace slag 21–35 %</td></tr><tr><td style="text-align:left;"><strong>CEM II/A-D</strong></td><td style="text-align:left;">Portland-silica fume</td><td style="text-align:right;">90–94 %</td><td style="text-align:left;">silica fume 6–10 %</td></tr><tr><td style="text-align:left;"><strong>CEM II/A-P, /A-Q</strong></td><td style="text-align:left;">Portland-pozzolana</td><td style="text-align:right;">80–94 %</td><td style="text-align:left;">natural (P) or calcined (Q) pozzolana 6–20 %</td></tr><tr><td style="text-align:left;"><strong>CEM II/B-P, /B-Q</strong></td><td style="text-align:left;">Portland-pozzolana</td><td style="text-align:right;">65–79 %</td><td style="text-align:left;">pozzolana 21–35 %</td></tr><tr><td style="text-align:left;"><strong>CEM II/A-V, /A-W</strong></td><td style="text-align:left;">Portland-fly ash</td><td style="text-align:right;">80–94 %</td><td style="text-align:left;">siliceous (V) or calcareous (W) fly ash 6–20 %</td></tr><tr><td style="text-align:left;"><strong>CEM II/B-V, /B-W</strong></td><td style="text-align:left;">Portland-fly ash</td><td style="text-align:right;">65–79 %</td><td style="text-align:left;">fly ash 21–35 %</td></tr><tr><td style="text-align:left;"><strong>CEM II/A-T, /B-T</strong></td><td style="text-align:left;">Portland-burnt shale</td><td style="text-align:right;">80–94 / 65–79 %</td><td style="text-align:left;">burnt shale 6–20 / 21–35 %</td></tr><tr><td style="text-align:left;"><strong>CEM II/A-L, /A-LL</strong></td><td style="text-align:left;">Portland-limestone</td><td style="text-align:right;">80–94 %</td><td style="text-align:left;">limestone 6–20 %</td></tr><tr><td style="text-align:left;"><strong>CEM II/B-L, /B-LL</strong></td><td style="text-align:left;">Portland-limestone</td><td style="text-align:right;">65–79 %</td><td style="text-align:left;">limestone 21–35 %</td></tr><tr><td style="text-align:left;"><strong>CEM II/A-M, /B-M</strong></td><td style="text-align:left;">Portland-composite</td><td style="text-align:right;">80–94 / 65–79 %</td><td style="text-align:left;">a mixture of the above</td></tr><tr><td style="text-align:left;"><strong>CEM III/A</strong></td><td style="text-align:left;">Blastfurnace</td><td style="text-align:right;">35–64 %</td><td style="text-align:left;">slag 36–65 %</td></tr><tr><td style="text-align:left;"><strong>CEM III/B</strong></td><td style="text-align:left;">Blastfurnace</td><td style="text-align:right;">20–34 %</td><td style="text-align:left;">slag 66–80 %</td></tr><tr><td style="text-align:left;"><strong>CEM III/C</strong></td><td style="text-align:left;">Blastfurnace</td><td style="text-align:right;">5–19 %</td><td style="text-align:left;">slag 81–95 %</td></tr><tr><td style="text-align:left;"><strong>CEM IV/A</strong></td><td style="text-align:left;">Pozzolanic</td><td style="text-align:right;">65–89 %</td><td style="text-align:left;">D + P + Q + V + W, 11–35 %</td></tr><tr><td style="text-align:left;"><strong>CEM IV/B</strong></td><td style="text-align:left;">Pozzolanic</td><td style="text-align:right;">45–64 %</td><td style="text-align:left;">D + P + Q + V + W, 36–55 %</td></tr><tr><td style="text-align:left;"><strong>CEM V/A</strong></td><td style="text-align:left;">Composite</td><td style="text-align:right;">40–64 %</td><td style="text-align:left;">slag 18–30 % <strong>and</strong> pozzolana/fly ash 18–30 %</td></tr><tr><td style="text-align:left;"><strong>CEM V/B</strong></td><td style="text-align:left;">Composite</td><td style="text-align:right;">20–38 %</td><td style="text-align:left;">slag 31–49 % <strong>and</strong> pozzolana/fly ash 31–49 %</td></tr></tbody></table><h3 id="The-letters" tabindex="-1">The letters <a class="header-anchor" href="#The-letters" aria-label="Permalink to &quot;The letters {#The-letters}&quot;">​</a></h3><p>EN 197-1 designates each constituent by a letter, and the composite families (<code>CEM II/*-M</code>, <code>CEM IV</code>, <code>CEM V</code>) use them without repeating the name. They are:</p><table tabindex="0"><thead><tr><th style="text-align:center;">letter</th><th style="text-align:left;">constituent</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>S</strong></td><td style="text-align:left;">blastfurnace slag</td></tr><tr><td style="text-align:center;"><strong>D</strong></td><td style="text-align:left;">silica fume — the letter is not a mnemonic in English; it is simply the code the standard assigns</td></tr><tr><td style="text-align:center;"><strong>P</strong></td><td style="text-align:left;">natural pozzolana</td></tr><tr><td style="text-align:center;"><strong>Q</strong></td><td style="text-align:left;">natural <strong>calcined</strong> pozzolana</td></tr><tr><td style="text-align:center;"><strong>V</strong></td><td style="text-align:left;">siliceous fly ash (low calcium)</td></tr><tr><td style="text-align:center;"><strong>W</strong></td><td style="text-align:left;">calcareous fly ash (high calcium)</td></tr><tr><td style="text-align:center;"><strong>T</strong></td><td style="text-align:left;">burnt shale</td></tr><tr><td style="text-align:center;"><strong>L</strong>, <strong>LL</strong></td><td style="text-align:left;">limestone — <code>LL</code> is the stricter grade, capped at 0.20 % total organic carbon against 0.50 % for <code>L</code></td></tr></tbody></table><p>So a <code>CEM V/A (S-V)</code> is a composite of slag <strong>and</strong> siliceous fly ash, and a <code>CEM IV/B (V)</code> is pozzolanic with siliceous fly ash alone. The letter in parentheses is what the binder actually contains, which the calculation needs and the type alone does not give.</p><div class="warning custom-block"><p class="custom-block-title">The standard is the authority, not this table</p><p>The ranges above summarize <strong>EN 197-1</strong>, <em>Cement — Part 1: Composition, specifications and conformity criteria for common cements</em>. They are given as context for choosing a composition to calculate; percentages are by mass of the main constituents, excluding calcium sulfate and minor additional constituents. Anything with consequences — a conformity claim, a specification — must be read from the standard itself, which this package does not ship and cannot substitute for.</p><p><strong>EN 197-5</strong> adds two families this table does not carry: CEM II/C-M and CEM VI, which push the replacement further than EN 197-1 allows.</p></div><h2 id="What-each-constituent-brings-to-the-chemistry" tabindex="-1">What each constituent brings to the chemistry <a class="header-anchor" href="#What-each-constituent-brings-to-the-chemistry" aria-label="Permalink to &quot;What each constituent brings to the chemistry {#What-each-constituent-brings-to-the-chemistry}&quot;">​</a></h2><p>The percentages matter because of what they <em>do</em>. Each constituent changes the element budget, and the element budget decides which hydrates the minimization can form.</p><table tabindex="0"><thead><tr><th style="text-align:left;">constituent</th><th style="text-align:left;">brings</th><th style="text-align:left;">consequence for the calculation</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>clinker</strong></td><td style="text-align:left;">Ca, Si, Al, Fe, and all of the heat</td><td style="text-align:left;">the reference case; see <a href="/ChemistryLab.jl/dev/examples/cem1_from_clinker#sec-cem1-from-clinker">CEM I from the clinker up</a></td></tr><tr><td style="text-align:left;"><strong>blastfurnace slag (S)</strong></td><td style="text-align:left;">Ca, Si, Al, <strong>Mg</strong>, and sulfur as <strong>S(-II)</strong></td><td style="text-align:left;">needs a <a href="/ChemistryLab.jl/dev/theory/redox#theory-redox">redox</a> treatment: the slag&#39;s sulfide meets the pore solution&#39;s sulfate, and both must be held at once. The Mg forms hydrotalcite</td></tr><tr><td style="text-align:left;"><strong>fly ash (V, W)</strong></td><td style="text-align:left;">Si, Al, alkalis; W also Ca</td><td style="text-align:left;">the Al goes into the C-S-H, which then needs <code>CNASH_ss</code> rather than <code>CSHQ</code></td></tr><tr><td style="text-align:left;"><strong>natural/calcined pozzolana (P, Q)</strong></td><td style="text-align:left;">Si, Al, alkalis</td><td style="text-align:left;">as fly ash, and at high alkali the zeolites become stable</td></tr><tr><td style="text-align:left;"><strong>silica fume (D)</strong></td><td style="text-align:left;">Si, and nothing else</td><td style="text-align:left;">lowers the Ca/Si of the C-S-H; no new phase family</td></tr><tr><td style="text-align:left;"><strong>limestone (L, LL)</strong></td><td style="text-align:left;"><strong>CO₃</strong></td><td style="text-align:left;">changes the aluminate sequence: monocarboaluminate forms instead of monosulphate, which stabilizes the ettringite</td></tr><tr><td style="text-align:left;"><strong>burnt shale (T)</strong></td><td style="text-align:left;">Ca, Si, Al, sulfate</td><td style="text-align:left;">behaves as a weak clinker plus a pozzolana</td></tr></tbody></table><p>Read the table as a list of <strong>model requirements</strong>, because that is what it is. A CEM I needs none of this package&#39;s later machinery; a CEM III needs the oxidation state to be a conserved quantity; a CEM IV or V needs a C-S-H that can take aluminum and alkalis.</p><p>Two things the table does not contain, and both belong to every row of it.</p><p><strong>The alkalis of the clinker.</strong> A Bogue calculation returns four phases and no Na₂O or K₂O — they are minor oxides, outside the decomposition — and they are what sets the pH of the pore solution, the calcium being held at the portlandite floor near 12.5. A budget entered through Bogue and nothing else returns that floor on every binder alike, which is a signature worth recognizing; see <a href="/ChemistryLab.jl/dev/manual/choosing_species#man-choosing-species">trap 4</a>.</p><p><strong>How much of each constituent has reacted.</strong> The percentages above are what was <em>put in</em>, not what has dissolved. A Gibbs minimization reacts everything it is handed, so the reacted fraction is part of posing the problem: capped for every constituent alike by the water and space available (<a href="/ChemistryLab.jl/dev/api/kinetics#ChemistryLab.powers_alpha_max-Tuple{Real}"><code>powers_alpha_max</code></a>, and <a href="/ChemistryLab.jl/dev/theory/cement_water_budget#sec-theory-water-budget">the water budget</a> for why that cap is not thermodynamics), and for a glass capped far lower still by its own dissolution rate — measured, at 28 days, at 38–49 % for a slag and about 20 % for a siliceous fly ash (<a href="/ChemistryLab.jl/dev/references#Durdzinski2017">Durdziński <em>et al.</em>, 2017</a>).</p><h2 id="What-the-heat-says-about-all-of-it" tabindex="-1">What the heat says about all of it <a class="header-anchor" href="#What-the-heat-says-about-all-of-it" aria-label="Permalink to &quot;What the heat says about all of it {#What-the-heat-says-about-all-of-it}&quot;">​</a></h2><p>Every joule of hydration heat comes from the clinker. Replacing clinker with anything lowers it, and the ordering of the measured records this package ships is exactly the ordering of the replacement:</p><table tabindex="0"><thead><tr><th style="text-align:left;">record</th><th style="text-align:left;">family</th><th style="text-align:right;">final <em>Q</em></th></tr></thead><tbody><tr><td style="text-align:left;"><code>122-cemI-52.5R-cizkovice</code></td><td style="text-align:left;">CEM I</td><td style="text-align:right;"><strong>376 J/g</strong></td></tr><tr><td style="text-align:left;"><code>116-cemI-52.5R-ladce</code></td><td style="text-align:left;">CEM I</td><td style="text-align:right;">355 J/g</td></tr><tr><td style="text-align:left;"><code>165-cemII-A-LL-42.5R-hranice</code></td><td style="text-align:left;">CEM II/A-LL</td><td style="text-align:right;">329 J/g</td></tr><tr><td style="text-align:left;"><code>149-cemII-B-S-32.5R-mokra</code></td><td style="text-align:left;">CEM II/B-S</td><td style="text-align:right;">296 J/g</td></tr><tr><td style="text-align:left;"><code>184-cemIII-A-42.5N-hranice</code></td><td style="text-align:left;">CEM III/A</td><td style="text-align:right;">261 J/g</td></tr><tr><td style="text-align:left;"><code>200-cemV-A-S-V-32.5R-prachovice</code></td><td style="text-align:left;">CEM V-A (S-V)</td><td style="text-align:right;">259 J/g</td></tr><tr><td style="text-align:left;"><code>121-cemIII-B-32.5N-mokra</code></td><td style="text-align:left;">CEM III/B</td><td style="text-align:right;"><strong>234 J/g</strong></td></tr></tbody></table><p>Measured on one instrument at 20 °C, from the CC-BY-4.0 deposit of Šmilauer and Reiterman (<a href="/ChemistryLab.jl/dev/references#Smilauer2025data">Šmilauer and Reiterman, 2025</a>); see <code>data/experimental/README.md</code> for the full provenance and for one inconsistency found in the source metadata.</p><div class="danger custom-block"><p class="custom-block-title">What these records do <strong>not</strong> report</p><p>The deposit gives the calorimetry, the Blaine fineness and the water/binder ratio. It gives <strong>neither the clinker phase composition nor the actual replacement level</strong> of any blend.</p><p>So a calculation of one of these cements has to <em>assume</em> a composition inside the EN 197-1 range of its family. Every page that does so says which number is measured and which is assumed, at the point of use. A page that presented &quot;40 % clinker&quot; as a property of the specimen would be inventing it, and the distinction matters most exactly where a reader is least able to check.</p></div><div class="tip custom-block"><p class="custom-block-title">Before you compute: which species to declare</p><p>Each line of the table above is also a <strong>requirement on the species list</strong>, and a Gibbs minimization cannot form a phase it was not given — nor will it tell you that the one it needed was missing. It reports a poor element balance, or a pH of 7, or an assemblage that looks almost right.</p><p><a href="/ChemistryLab.jl/dev/manual/choosing_species#man-choosing-species">Choosing the species list</a> is the check-list, with the six traps that were met while writing this manual and what each looked like when it happened.</p></div><h2 id="Where-the-calculations-are" tabindex="-1">Where the calculations are <a class="header-anchor" href="#Where-the-calculations-are" aria-label="Permalink to &quot;Where the calculations are {#Where-the-calculations-are}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">page</th><th style="text-align:left;">what it does</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/ChemistryLab.jl/dev/examples/bogue_calculation#Bogue-Calculation">Bogue Calculation</a></td><td style="text-align:left;">an oxide analysis to clinker phases — the entry point for a CEM I</td></tr><tr><td style="text-align:left;"><a href="/ChemistryLab.jl/dev/examples/cem1_from_clinker#sec-cem1-from-clinker">CEM I from the clinker up</a></td><td style="text-align:left;">the reference paste, hydrated and certified</td></tr><tr><td style="text-align:left;"><a href="/ChemistryLab.jl/dev/examples/cem1_solid_solutions#A-CEM-I-at-equilibrium,-with-every-solid-solution-declared">A CEM I at equilibrium, with every solid solution declared</a></td><td style="text-align:left;">the phase list as a modeling decision</td></tr><tr><td style="text-align:left;"><a href="/ChemistryLab.jl/dev/examples/ionic_hydration#ex-ionic-opc">The full Portland cement, through its pore solution</a></td><td style="text-align:left;">the coupled run, and its calorimetry</td></tr><tr><td style="text-align:left;"><a href="/ChemistryLab.jl/dev/examples/hydration_calibration#ex-hydration-calibration">Calibrating hydration kinetics</a></td><td style="text-align:left;">the inverse problem, against measured calorimetry</td></tr></tbody></table><p>And one page per blended family, each on the same shape — element budget in, certified assemblage out, measured calorimetry beside it:</p><table tabindex="0"><thead><tr><th style="text-align:left;">page</th><th style="text-align:left;">family</th><th style="text-align:left;">what it is about</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/ChemistryLab.jl/dev/examples/cem2_blended#ex-cem2-blended">Two CEM II, and the two different things a replacement can do</a></td><td style="text-align:left;">CEM II</td><td style="text-align:left;">a carbonate that rewrites the aluminate sequence, against a glass that brings magnesium</td></tr><tr><td style="text-align:left;"><a href="/ChemistryLab.jl/dev/examples/cem3_slag#ex-cem3-slag">A blastfurnace cement, and the oxidation state it needs</a></td><td style="text-align:left;">CEM III</td><td style="text-align:left;">the glass entry route, hydrotalcite, and sulfur at two oxidation states</td></tr><tr><td style="text-align:left;"><a href="/ChemistryLab.jl/dev/examples/cem4_pozzolanic#ex-cem4-pozzolanic">A pozzolanic binder, and the C-S-H that has to carry the aluminum</a></td><td style="text-align:left;">CEM IV</td><td style="text-align:left;"><code>CSHQ</code> against <code>CNASH_ss</code>, and portlandite as the limiting reagent</td></tr><tr><td style="text-align:left;"><a href="/ChemistryLab.jl/dev/examples/cem5_composite#ex-cem5-composite">A composite binder: two glasses at once</a></td><td style="text-align:left;">CEM V</td><td style="text-align:left;">all four difficulties simultaneously, on one additive budget</td></tr></tbody></table><p>The CEM IV page is the one without a measured specimen behind it — the deposit carries no record of that family — and it says so at its head rather than in a footnote.</p>',28)])])}const y=e(n,[["render",i]]);export{f as __pageData,y as default};
